import{_ as i,c as a,o as r,ag as n}from"./chunks/framework.0-OC-noK.js";const u=JSON.parse('{"title":"API Specification","description":"Kirox CLI API specification","frontmatter":{"title":"API Specification","description":"Kirox CLI API specification"},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md"}'),t={name:"api/index.md"};function s(l,e,o,c,p,d){return r(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="api-specification" tabindex="-1">API Specification <a class="header-anchor" href="#api-specification" aria-label="Permalink to &quot;API Specification&quot;">​</a></h1><p>API specification for Kirox CLI&#39;s major modules.</p><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>Kirox CLI adopts a Layer-Based Architecture:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CLI Layer (src/cli/)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>GitHub Integration Layer (src/github/)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>File System Layer (src/filesystem/)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Reporting Layer (src/reporting/)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="major-modules" tabindex="-1">Major Modules <a class="header-anchor" href="#major-modules" aria-label="Permalink to &quot;Major Modules&quot;">​</a></h2><h3 id="github-fetcher" tabindex="-1"><a href="/kirox/api/github-fetcher.html">GitHub Fetcher</a> <a class="header-anchor" href="#github-fetcher" aria-label="Permalink to &quot;[GitHub Fetcher](/api/github-fetcher)&quot;">​</a></h3><p>Module for fetching files from GitHub repositories.</p><p><strong>Responsibilities</strong>:</p><ul><li>Communication with GitHub API</li><li>Fetching repository content</li><li>Decoding base64-encoded content</li><li>Parallel file fetching and semaphore control</li><li>Rate limit monitoring and handling</li></ul><h3 id="filesystem-writer" tabindex="-1"><a href="/kirox/api/filesystem-writer.html">FileSystem Writer</a> <a class="header-anchor" href="#filesystem-writer" aria-label="Permalink to &quot;[FileSystem Writer](/api/filesystem-writer)&quot;">​</a></h3><p>Module for writing files to the local filesystem.</p><p><strong>Responsibilities</strong>:</p><ul><li>Writing to local filesystem</li><li>Automatic directory creation</li><li>Existing file overwrite confirmation prompt</li><li>--dry-run mode processing</li></ul><h2 id="architecture-principles" tabindex="-1">Architecture Principles <a class="header-anchor" href="#architecture-principles" aria-label="Permalink to &quot;Architecture Principles&quot;">​</a></h2><h3 id="_1-single-responsibility-principle-srp" tabindex="-1">1. Single Responsibility Principle (SRP) <a class="header-anchor" href="#_1-single-responsibility-principle-srp" aria-label="Permalink to &quot;1. Single Responsibility Principle (SRP)&quot;">​</a></h3><p>Each component has a single responsibility.</p><h3 id="_2-dependency-inversion-principle-dip" tabindex="-1">2. Dependency Inversion Principle (DIP) <a class="header-anchor" href="#_2-dependency-inversion-principle-dip" aria-label="Permalink to &quot;2. Dependency Inversion Principle (DIP)&quot;">​</a></h3><p>Upper layers depend on abstractions (interfaces), not on concrete implementations.</p><h3 id="_3-layer-isolation" tabindex="-1">3. Layer Isolation <a class="header-anchor" href="#_3-layer-isolation" aria-label="Permalink to &quot;3. Layer Isolation&quot;">​</a></h3><p>Minimize direct dependencies between layers; GitHub and FileSystem layers don&#39;t depend on each other.</p><h2 id="development-guidelines" tabindex="-1">Development Guidelines <a class="header-anchor" href="#development-guidelines" aria-label="Permalink to &quot;Development Guidelines&quot;">​</a></h2><h3 id="typescript" tabindex="-1">TypeScript <a class="header-anchor" href="#typescript" aria-label="Permalink to &quot;TypeScript&quot;">​</a></h3><ul><li><strong>Strict type checking</strong>: <code>strict: true</code></li><li><strong>No <code>any</code></strong>: Enforce explicit type definitions</li><li><strong>Explicit return types</strong>: Explicitly specify function return types instead of relying on inference</li></ul><h3 id="naming" tabindex="-1">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to &quot;Naming&quot;">​</a></h3><ul><li><strong>Functions</strong>: Camel case starting with verbs (<code>fetchFiles</code>, <code>validateInput</code>)</li><li><strong>Classes</strong>: Noun-based Pascal case (<code>GitHubFetcher</code>, <code>ProgressReporter</code>)</li><li><strong>Constants</strong>: Upper snake case (<code>MAX_CONCURRENCY</code>, <code>DEFAULT_CONFIG</code>)</li></ul><h3 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h3><ul><li><strong>Custom error classes</strong>: Define domain-specific error types</li><li><strong>Proper error propagation</strong>: Don&#39;t suppress errors with try-catch</li></ul><h3 id="async-await" tabindex="-1">Async/Await <a class="header-anchor" href="#async-await" aria-label="Permalink to &quot;Async/Await&quot;">​</a></h3><ul><li><strong>No Promise chains</strong>: Prefer async/await</li><li><strong>Parallel processing</strong>: Use <code>Promise.all()</code> / <code>Promise.allSettled()</code></li></ul><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><ul><li><strong>Parallel file fetching</strong>: Max 5 concurrent</li><li><strong>Large file fetching</strong>: Within 30 seconds for 50 files</li><li><strong>Memory usage</strong>: Within 100MB for 100 files</li><li><strong>Rate limit avoidance</strong>: No GitHub API rate limit violation for 100 files</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/kirox/api/github-fetcher.html">GitHub Fetcher API</a>: Details on GitHub integration</li><li><a href="/kirox/api/filesystem-writer.html">FileSystem Writer API</a>: Details on filesystem operations</li></ul>`,34)])])}const m=i(t,[["render",s]]);export{u as __pageData,m as default};
